import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CdvW4CUT.js";const d=JSON.parse('{"title":"快速入门","description":"","frontmatter":{},"headers":[],"relativePath":"school/quick_start.md","filePath":"school/quick_start.md"}'),r={name:"school/quick_start.md"};function o(h,a,s,n,c,p){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to &quot;快速入门&quot;">​</a></h1><blockquote><p>esp32、stm32、树莓派、ch32</p></blockquote><h2 id="前置准备" tabindex="-1">前置准备 <a class="header-anchor" href="#前置准备" aria-label="Permalink to &quot;前置准备&quot;">​</a></h2><ul><li>一台可以正常上网的windows/mac设备</li><li>数据线（带下载）</li><li>开发板（ESP32、stm32、pyboard等）</li></ul><h2 id="选购开发版" tabindex="-1">选购开发版 <a class="header-anchor" href="#选购开发版" aria-label="Permalink to &quot;选购开发版&quot;">​</a></h2><p>国内常见开发板子主要是ESP32、stm32、树莓派等，也有许多新兴芯片如GD32、CH32等，主要是rise-v和arm架构的芯片，这里不再赘述，有兴趣可以在网上自行寻找资源进行学习。</p><h2 id="推荐开发板" tabindex="-1">推荐开发板 <a class="header-anchor" href="#推荐开发板" aria-label="Permalink to &quot;推荐开发板&quot;">​</a></h2><h3 id="esp32-s3-n16r8" tabindex="-1">ESP32-S3 N16R8 <a class="header-anchor" href="#esp32-s3-n16r8" aria-label="Permalink to &quot;ESP32-S3 N16R8&quot;">​</a></h3><p>价格：20-30元 N指的是存储空间为16M，RAM8M，可以按照需求购买，但是大容量与小容量价格相差无几建议购买大容量</p><p>推荐理由：</p><ul><li>外设丰富WIFI、蓝牙、ziggbe、espnow通信协议兼备，SPI，I2C，I2S，ADC，DAC，USB，PWM</li><li>开发语言多样：ardunio、esp-idf、c、micropython均可</li><li>双核处理器</li></ul><h3 id="stm32f103c8t6" tabindex="-1">stm32f103c8t6 <a class="header-anchor" href="#stm32f103c8t6" aria-label="Permalink to &quot;stm32f103c8t6&quot;">​</a></h3><p>价格：5-15元</p><p>推荐理由：</p><ul><li>资料丰富</li></ul><h3 id="rp2040" tabindex="-1">RP2040 <a class="header-anchor" href="#rp2040" aria-label="Permalink to &quot;RP2040&quot;">​</a></h3><p>价格：10-15元</p><p>推荐理由：</p><ul><li>语言：micropython</li><li>多数不带通信模块</li><li>pio</li></ul><h2 id="烧录设备选择" tabindex="-1">烧录设备选择 <a class="header-anchor" href="#烧录设备选择" aria-label="Permalink to &quot;烧录设备选择&quot;">​</a></h2><ul><li>CH340</li></ul><p>ESP32系列均可使用，正常情况下无需单独购买，开发板板载下载芯片，只需安装驱动即可</p><ul><li>ST-LINk</li></ul><p>STM32系列设备必买，支持下载、调试</p><ul><li>树莓派</li></ul><p>无需额外购买</p><ul><li>ch32</li></ul><p>WCH-LINKE\\WCH-LINK 详情可询问客服</p><h2 id="驱动下载安装" tabindex="-1">驱动下载安装 <a class="header-anchor" href="#驱动下载安装" aria-label="Permalink to &quot;驱动下载安装&quot;">​</a></h2><p>设备管理器-&gt;选中新插入设备，在线安装驱动，如果安装失败，问客服要驱动程序安装即可</p><h2 id="开发环境配置" tabindex="-1">开发环境配置 <a class="header-anchor" href="#开发环境配置" aria-label="Permalink to &quot;开发环境配置&quot;">​</a></h2><ul><li><p>MicroPython <a href="https://thonny.org/">点击下载thonny</a> ESP32、树莓派可用，浏览器下载thonny即可</p></li><li><p>esp-idf</p></li></ul><p>esp32专用，比较复杂</p><ul><li>keil stm32专用，比较复杂</li></ul><h2 id="工程创建" tabindex="-1">工程创建 <a class="header-anchor" href="#工程创建" aria-label="Permalink to &quot;工程创建&quot;">​</a></h2><h2 id="程序下载" tabindex="-1">程序下载 <a class="header-anchor" href="#程序下载" aria-label="Permalink to &quot;程序下载&quot;">​</a></h2>',36)])])}const m=l(r,[["render",o]]);export{d as __pageData,m as default};
